/* Graphite - generated by tools/build.mjs from src/scripts/web-recolor.js. Do not edit. */
/*
 * Graphite web recolor.
 *
 * Valve's newer React pages on store.steampowered.com / steamcommunity.com
 * (wishlist, calendar, news hub, charts, ...) hardcode their blue-grey
 * palette in CSS behind hashed class names that change with every deploy.
 * Instead of chasing those classes, this script looks at the *computed*
 * colors and swaps Valve's characteristic dark blue-greys for Graphite's
 * neutral surfaces (and Valve's bright blues for the accent).
 *
 * - Only touches colors that are clearly "Valve blue": a blue tint on a dark
 *   surface, or Steam's link/button blues. Images, game art, rarity colors,
 *   greens, reds and the Graphite colors themselves are left alone.
 * - Runs once on load and then only on newly added DOM subtrees, batched
 *   into idle time.
 * - Fully local; no network access.
 * - Also tags the parts of a few redesigned React pages (wishlist) with
 *   stable gr-* classes for the theme CSS; see "Structure hooks".
 */
(() => {
	if (window.__graphiteRecolor) return;
	window.__graphiteRecolor = true;

	const DONE = 'grRecolored';
	const applied = new WeakMap(); // element -> properties we set

	const parse = s => {
		const m = s && s.match(/rgba?\(\s*([\d.]+)[ ,]+([\d.]+)[ ,]+([\d.]+)(?:[ ,/]+([\d.]+))?/);
		return m ? { r: +m[1], g: +m[2], b: +m[3], a: m[4] === undefined ? 1 : +m[4] } : null;
	};
	const lum = c => (0.2126 * c.r + 0.7152 * c.g + 0.0722 * c.b) / 255;

	// "Valve blue-grey": dark-ish, blue clearly above red, not a saturated hue
	const isSurfaceBlue = c => c.b > 20 && c.b - c.r >= 10 && c.b >= c.g && lum(c) < 0.42 && c.b - c.r < 90;
	// bright Steam blues used for links / primary buttons / highlights
	const isBrightBlue = c => c.b > 180 && c.b - c.r > 90 && lum(c) > 0.3;

	const surface = l => (l < 0.075 ? '--gr-bg' : l < 0.115 ? '--gr-surface' : l < 0.17 ? '--gr-surface-2' : '--gr-surface-3');
	const alpha = (v, a) => (a >= 0.99 ? `var(${v})` : `color-mix(in srgb, var(${v}) ${Math.round(a * 100)}%, transparent)`);

	function recolor(el) {
		if (el.dataset && el.dataset[DONE]) return;
		const cs = getComputedStyle(el);
		const set = [];
		// parts restyled by Graphite's own CSS (see hooks below): leave their
		// surfaces alone, only fix text colors
		const hooked = !!(el.closest && el.closest('[data-gr-hook]'));
		if (hooked) {
			textColor(el, cs, set);
			for (const [p, v] of set) el.style.setProperty(p, v, 'important');
			if (set.length) applied.set(el, set.map(([p]) => p));
			if (el.dataset) el.dataset[DONE] = '1';
			return;
		}

		const bg = parse(cs.backgroundColor);
		if (bg && bg.a > 0.05) {
			if (isSurfaceBlue(bg)) set.push(['background-color', alpha(surface(lum(bg)), bg.a)]);
			else if (isBrightBlue(bg)) set.push(['background-color', 'var(--gr-accent)'], ['color', 'var(--gr-bg)']);
		}

		const img = cs.backgroundImage;
		if (img && img !== 'none' && !img.includes('url(') && img.includes('gradient')) {
			const stops = [...img.matchAll(/rgba?\([^)]+\)/g)].map(m => parse(m[0])).filter(Boolean);
			const blue = stops.filter(c => c.a > 0.05 && (isSurfaceBlue(c) || isBrightBlue(c)));
			if (blue.length && blue.length >= stops.filter(c => c.a > 0.05).length / 2) {
				set.push(['background-image', 'none']);
				const opaque = stops.filter(c => c.a > 0.5);
				if (opaque.length) {
					const avg = opaque.reduce((s, c) => s + lum(c), 0) / opaque.length;
					if (opaque.some(isBrightBlue)) set.push(['background-color', 'var(--gr-accent)'], ['color', 'var(--gr-bg)']);
					else set.push(['background-color', `var(${surface(avg)})`]);
				}
			}
		}

		for (const side of ['top', 'right', 'bottom', 'left']) {
			if (cs[`border-${side}-style`] === 'none' || cs[`border-${side}-width`] === '0px') continue;
			const c = parse(cs[`border-${side}-color`]);
			if (c && c.a > 0.05 && (isSurfaceBlue(c) || isBrightBlue(c))) set.push([`border-${side}-color`, 'var(--gr-border)']);
		}

		textColor(el, cs, set);

		for (const [p, v] of set) el.style.setProperty(p, v, 'important');
		if (set.length) applied.set(el, set.map(([p]) => p));
		if (el.dataset) el.dataset[DONE] = '1';
	}

	// light-blue link / label text -> accent (only leaf-ish text elements)
	function textColor(el, cs, set) {
		if (set.some(([p]) => p === 'color') || el.childElementCount > 1) return;
		const t = parse(cs.color);
		if (t && t.b > 170 && t.b - t.r > 60 && lum(t) > 0.35) set.push(['color', 'var(--gr-accent)']);
	}

	/*
	 * Structure hooks. Some React pages are worth a real redesign, but their
	 * class names are hashed and change with every store deploy. So the
	 * parts are found by structure (links, inputs, buttons) and tagged with
	 * stable gr-* classes that the theme CSS styles (web-wishlist.css).
	 */
	const unrecolor = root => {
		for (const el of [root, ...root.querySelectorAll('*')]) {
			const props = applied.get(el);
			if (props) { props.forEach(p => el.style.removeProperty(p)); applied.delete(el); }
			if (el.dataset) delete el.dataset[DONE];
		}
	};
	const hook = (el, cls) => {
		if (!el || el.classList.contains(cls)) return;
		el.classList.add(cls);
		if (!el.closest('[data-gr-hook]')) { el.dataset.grHook = ''; unrecolor(el); }
	};
	const leaves = root => [...root.querySelectorAll('*')].filter(e => !e.children.length && !(e instanceof SVGElement));

	const ROLES = ['gr-wl-rank', 'gr-wl-name', 'gr-wl-buy', 'gr-wl-added', 'gr-wl-cats', 'gr-wl-info'];
	function hookWishlist() {
		if (!/^\/wishlist\//.test(location.pathname)) return;
		document.documentElement.classList.add('gr-wishlist');

		// page header and toolbar
		const search = [...document.querySelectorAll('input[placeholder]')]
			.find(i => i.type === 'text' && !i.closest('form') && i.getBoundingClientRect().width > 300); // (the store search is a form)
		if (search) {
			const bar = search.parentElement;
			hook(bar, 'gr-wl-toolbar');
			const count = bar.nextElementSibling;
			if (count && !count.querySelector('a, input')) hook(count, 'gr-wl-count');
			const head = bar.previousElementSibling;
			if (head && head.querySelector('h2')) {
				hook(head, 'gr-wl-head');
				// Valve writes the heading in capitals; the page title has the
				// same words in normal case, so CSS shows that instead (the
				// React-owned text node itself stays untouched)
				const h2 = head.querySelector('h2');
				const title = document.title.replace(/\s*::.*$/, '').trim();
				if (title && h2.textContent.trim().toUpperCase() === title.toUpperCase()) h2.dataset.grTitle = title;
			}
		}

		// one card per wishlist entry: the capsule link (with image) sits
		// directly in the card, next to title, details, price and "added"
		for (const cap of document.querySelectorAll('a[href*="/app/"]')) {
			if (!cap.querySelector('img')) continue;
			const row = cap.parentElement;
			// (re-run on every pass: React fills cards in over several renders)
			if (!row || row.getBoundingClientRect().width < 600) continue;
			hook(row, 'gr-wl-row');
			if (!cap.classList.contains('gr-wl-cap')) cap.classList.add('gr-wl-cap');
			// work out each part's role first, then only touch classes that
			// actually change (re-adding them would restart CSS transitions)
			const role = new Map();
			const rest = [];
			for (const c of row.children) {
				if (c === cap) continue;
				const app = c.querySelector('a[href*="/app/"]');
				const btn = c.querySelector('button');
				if (c.querySelector('input') && !app) role.set(c, 'gr-wl-rank');
				else if (app && !btn) role.set(c, 'gr-wl-name');
				else if (app && btn) role.set(c, 'gr-wl-buy');
				else rest.push(c);
			}
			// remaining: "added on / remove" (top right), categories, details
			const rr = row.getBoundingClientRect();
			const added = rest.find(c => { const r = c.getBoundingClientRect(); return r.top - rr.top < 30 && rr.right - r.right < 40; });
			if (added) role.set(added, 'gr-wl-added');
			// details = the block with the tag buttons (or, without tags, the
			// one with the most text); categories = the top block with one button
			const others = rest.filter(c => c !== added && c.textContent.trim());
			const score = c => c.querySelectorAll('button').length * 100 + c.textContent.length;
			const info = others.slice().sort((x, y) => score(y) - score(x))[0];
			if (info) role.set(info, 'gr-wl-info');
			const cats = others.filter(c => c !== info && c.querySelectorAll('button').length === 1)
				.sort((x, y) => x.getBoundingClientRect().top - y.getBoundingClientRect().top)[0];
			if (cats) role.set(cats, 'gr-wl-cats');
			for (const c of row.children) {
				if (c === cap) continue;
				const want = role.get(c);
				for (const k of ROLES) if (k !== want && c.classList.contains(k)) c.classList.remove(k);
				if (want && !c.classList.contains(want)) c.classList.add(want);
			}
			for (const l of leaves(row)) if (/:\s*$/.test(l.textContent) && !l.classList.contains('gr-wl-label')) l.classList.add('gr-wl-label');
			if (info) info.querySelectorAll('button:not(.gr-wl-tag)').forEach(t => t.classList.add('gr-wl-tag'));
			const buy = row.querySelector('.gr-wl-buy');
			if (buy) buy.querySelectorAll('button:not(.gr-wl-cart)').forEach(t => t.classList.add('gr-wl-cart'));
		}
	}

	// store navigation search button: Valve paints it bright blue on some pages
	function hookStoreNav() {
		if (location.hostname !== 'store.steampowered.com') return;
		for (const b of document.querySelectorAll('button')) {
			if (b.classList.contains('gr-navsearch')) continue;
			const r = b.getBoundingClientRect();
			if (r.top > 70 || r.height === 0 || r.width > 60) continue;
			const bg = parse(getComputedStyle(b).backgroundColor);
			if (bg && isBrightBlue(bg)) hook(b, 'gr-navsearch');
		}
	}

	const queue = new Set();
	let scheduled = false;
	const idle = window.requestIdleCallback || (fn => setTimeout(() => fn({ timeRemaining: () => 8 }), 50));

	function flush(deadline) {
		scheduled = false;
		try { hookWishlist(); hookStoreNav(); } catch (e) { /* never break the page */ }
		for (const root of queue) {
			queue.delete(root);
			if (!root.isConnected) continue;
			recolor(root);
			for (const el of root.querySelectorAll('*')) {
				if (el instanceof SVGElement || el.tagName === 'IMG' || el.tagName === 'VIDEO' || el.tagName === 'CANVAS') continue;
				recolor(el);
			}
			if (deadline.timeRemaining() < 2) break;
		}
		if (queue.size) schedule();
	}
	function schedule() {
		if (!scheduled) { scheduled = true; idle(flush); }
	}
	function add(node) {
		if (node.nodeType === 1) { queue.add(node); schedule(); }
	}

	function start() {
		add(document.body);
		new MutationObserver(muts => {
			for (const m of muts) {
				if (m.type === 'childList') m.addedNodes.forEach(add);
				else if (m.type === 'attributes' && m.target.dataset) {
					// class change (selected / active state): drop our overrides so the
					// page's real color for the new state is visible, then re-evaluate
					const props = applied.get(m.target);
					if (props) { props.forEach(p => m.target.style.removeProperty(p)); applied.delete(m.target); }
					delete m.target.dataset[DONE];
					queue.add(m.target); schedule();
				}
			}
		}).observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
	}

	if (document.body) start();
	else document.addEventListener('DOMContentLoaded', start, { once: true });
})();
